begin;

-- Nettoyage de l'éventuel voyage de démo précédent
delete from public.activity_reviews where wish_id in (select w.id from public.wishes w join public.trips t on t.id = w.trip_id where t.name = 'Road trip en Colombie' and t.owner_id = '6e9da77a-0648-4d86-b5de-139136c35692');
delete from public.expense_splits where expense_id in (select e.id from public.expenses e join public.trips t on t.id = e.trip_id where t.name = 'Road trip en Colombie' and t.owner_id = '6e9da77a-0648-4d86-b5de-139136c35692');
delete from public.planning_items where trip_id in (select id from public.trips where name = 'Road trip en Colombie' and owner_id = '6e9da77a-0648-4d86-b5de-139136c35692');
delete from public.expenses where trip_id in (select id from public.trips where name = 'Road trip en Colombie' and owner_id = '6e9da77a-0648-4d86-b5de-139136c35692');
delete from public.trip_photos where trip_id in (select id from public.trips where name = 'Road trip en Colombie' and owner_id = '6e9da77a-0648-4d86-b5de-139136c35692');
delete from public.wishes where trip_id in (select id from public.trips where name = 'Road trip en Colombie' and owner_id = '6e9da77a-0648-4d86-b5de-139136c35692');
delete from public.trip_stops where trip_id in (select id from public.trips where name = 'Road trip en Colombie' and owner_id = '6e9da77a-0648-4d86-b5de-139136c35692');
delete from public.trip_members where trip_id in (select id from public.trips where name = 'Road trip en Colombie' and owner_id = '6e9da77a-0648-4d86-b5de-139136c35692');
